// Package web serves the static cover hash lookup page.
//
// The static directory must contain main.wasm and wasm_exec.js, generated by
// web/build.sh before building comic-hasher.
package web

import (
	"bytes"
	"embed"
	"io/fs"
	"net/http"
	"path"
	"strconv"
	"strings"
	"time"
)

//go:embed static
var static embed.FS

type Static struct {
	domains []byte
	index   []byte
	sub     fs.FS
	files   http.Handler
	version string
}

func NewHandler() Static {
	sub, err := fs.Sub(static, "static")
	if err != nil {
		panic(err)
	}
	indexTemplate, err := fs.ReadFile(sub, "index.html")
	if err != nil {
		panic(err)
	}
	version := strconv.FormatInt(time.Now().Unix(), 10)
	s := Static{
		version: version,
		index:   bytes.ReplaceAll(indexTemplate, []byte("{{version}}"), []byte(version)),
		files:   http.FileServerFS(sub),
		sub:     sub,
	}
	return s
}

const template = `
<button class="menu-item" type="button" data-bs-value="{{domain}}">
<img width="16" height="16" loading="lazy" referrerpolicy="no-referrer" alt="{{domain}}" title="{{domain}}" src="{{domain}}.ico?v={{version}}">
{{domain}}
<img src="check.svg?v={{version}}" class="menu-item-check">
</button>`

func (s *Static) UpdateDomains(domains []string) {
	var domain string
	domainLen := 0
	for _, domain = range domains {
		domainLen = max(domainLen, len(domain))
	}
	b := bytes.NewBuffer(make([]byte, 0, (len(template)-10*5+11+15+domainLen)*len(domains)))
	for _, domain := range domains {
		b.Write(bytes.ReplaceAll(
			bytes.ReplaceAll([]byte(template), []byte("{{domain}}"), []byte(domain)),
			[]byte("{{version}}"), []byte(s.version),
		))
	}
	s.domains = b.Bytes()
}

func (s *Static) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path == "/" || r.URL.Path == "/index.html" {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.Header().Set("Cache-Control", "no-cache")
		_, _ = w.Write(bytes.Replace(s.index, []byte("{{domains}}"), s.domains, 1))
		return
	}
	if _, err := fs.Stat(s.sub, strings.TrimPrefix(path.Clean(r.URL.Path), "/")); err == nil {
		w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
	}
	s.files.ServeHTTP(w, r)
}
